function collectLines(chunks) {
  const lines = [];
  let rest = "";
  for (const chunk of chunks) {
    const parts = (rest + chunk).split("\n");
    rest = parts.pop();
    lines.push(...parts);
  }
  if (rest !== "") lines.push(rest);
  return lines;
}

console.log(JSON.stringify(collectLines(["task 1 op", "en\ntask 2 d", "one\ntask 3"])));
console.log(JSON.stringify(collectLines(["a\n", "b\n"])));

