function countLog(lines) {
  let lineCount = 0;
  let wordCount = 0;
  let doneCount = 0;
  for (const line of lines) {
    lineCount++;
    wordCount += line.split(" ").filter((word) => word !== "").length;
    if (line.includes(" done ")) doneCount++;
  }
  return { lineCount, wordCount, doneCount };
}

const lines = [
  "task 1 open buy milk",
  "task 2 done call ada",
  "task  3 open  pay rent ",
];
console.log(JSON.stringify(countLog(lines)));

