function utf8Length(text) {
  let bytes = 0;
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (code < 128) bytes += 1;
    else if (code < 2048) bytes += 2;
    else if (code < 65536) bytes += 3;
    else bytes += 4;
  }
  return bytes;
}

console.log(utf8Length("hello"), utf8Length("héllo"), utf8Length("€"), utf8Length("done ✅"), utf8Length("😀"));

function chunkStats(sizes) {
  let chunks = 0;
  let bytes = 0;
  let biggest = 0;
  for (const size of sizes) {
    chunks++;
    bytes += size;
    biggest = Math.max(biggest, size);
  }
  return { chunks, bytes, biggest };
}

console.log(JSON.stringify(chunkStats([65536, 65536, 8928])));

