function makeStream(limit) {
  let waiting = 0;
  const stream = {
    written: [],
    write(line) {
      stream.written.push(line);
      waiting += line.length;
      return waiting < limit;
    },
    drain() {
      waiting = 0;
    },
  };
  return stream;
}

function writeAll(stream, lines) {
  let pauses = 0;
  for (const line of lines) {
    if (!stream.write(line)) {
      pauses++;
      stream.drain();
    }
  }
  return pauses;
}

const stream = makeStream(10);
const lines = Array.from({ length: 10 }, (_, i) => `ln${i}\n`);
console.log(writeAll(stream, lines), stream.written.length);

